const { fonte } = $json;

return [{
  json: {
    inicio: Date.now(),
    versaoApi: 'v2',
    fonte,
    url: 'https://www.googleapis.com/tagmanager/v2/accounts',
  },
}];

function falhaDe(resposta) {
  if (resposta.error) return { causa: 'api_recusou', detalhe: `falha de rede: ${resposta.error?.message ?? resposta.error}`.slice(0, 500) };
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = resposta.body?.error;
  const detalhe = String(erro?.message || `HTTP ${resposta.statusCode}`).slice(0, 500);
  const configuracaoDoProjeto = resposta.statusCode === 429 || /SERVICE_DISABLED|accessNotConfigured|has not been used in project|RESOURCE_EXHAUSTED|RATE_LIMIT/.test(JSON.stringify(erro ?? {}));
  const semAcesso = !configuracaoDoProjeto && (resposta.statusCode === 401 || resposta.statusCode === 403);
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

const resposta = $input.first().json;
const falha = falhaDe(resposta);
if (falha) return [{ json: { falha } }];

const contas = resposta.body?.account ?? [];
if (contas.length === 0) return [{ json: { falha: { causa: 'api_recusou', detalhe: 'credencial não enxerga nenhuma conta do GTM' } } }];
return contas.map((conta) => ({ json: { path: conta.path } }));

function falhaDe(resposta) {
  if (resposta.error) return { causa: 'api_recusou', detalhe: `falha de rede: ${resposta.error?.message ?? resposta.error}`.slice(0, 500) };
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = resposta.body?.error;
  const detalhe = String(erro?.message || `HTTP ${resposta.statusCode}`).slice(0, 500);
  const configuracaoDoProjeto = resposta.statusCode === 429 || /SERVICE_DISABLED|accessNotConfigured|has not been used in project|RESOURCE_EXHAUSTED|RATE_LIMIT/.test(JSON.stringify(erro ?? {}));
  const semAcesso = !configuracaoDoProjeto && (resposta.statusCode === 401 || resposta.statusCode === 403);
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

const publicId = String($('Montar requisição').first().json.fonte.externalId);
const respostas = $input.all().map((item) => item.json);
const falha = respostas.map(falhaDe).find(Boolean);
if (falha) return [{ json: { falha } }];

const container = respostas.flatMap((resposta) => resposta.body?.container ?? []).find((item) => item.publicId === publicId);
if (!container) return [{ json: { falha: { causa: 'api_recusou', detalhe: `contêiner ${publicId} não aparece para esta credencial` } } }];
return [{
  json: {
    path: container.path,
    name: container.name,
    accountId: container.accountId ?? null,
    containerId: container.containerId ?? null,
    usageContext: Array.isArray(container.usageContext) ? container.usageContext.join(',') : null,
    domainName: Array.isArray(container.domainName) ? container.domainName.join(',') : null,
  },
}];

function falhaDe(resposta) {
  if (resposta.error) return { causa: 'api_recusou', detalhe: `falha de rede: ${resposta.error?.message ?? resposta.error}`.slice(0, 500) };
  if (resposta.statusCode >= 200 && resposta.statusCode < 300) return null;
  const erro = resposta.body?.error;
  const detalhe = String(erro?.message || `HTTP ${resposta.statusCode}`).slice(0, 500);
  const configuracaoDoProjeto = resposta.statusCode === 429 || /SERVICE_DISABLED|accessNotConfigured|has not been used in project|RESOURCE_EXHAUSTED|RATE_LIMIT/.test(JSON.stringify(erro ?? {}));
  const semAcesso = !configuracaoDoProjeto && (resposta.statusCode === 401 || resposta.statusCode === 403);
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

const contexto = $('Montar requisição').first().json;

function respostasDe(nome) {
  try {
    return $(nome).all().map((item) => item.json);
  } catch {
    return [];
  }
}

const chamadas = [...respostasDe('Listar contas'), ...respostasDe('Listar contêineres'), ...respostasDe('Versão publicada'), ...respostasDe('Workspaces')];
const requests = chamadas.length;
const bytes = chamadas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const entrada = $input.first().json;
if (entrada.falha) return devolver([], [entrada.falha]);
const atual = respostasDe('Versão publicada')[0] ?? {};
const respostaDosWorkspaces = respostasDe('Workspaces')[0] ?? {};

const semVersao = atual.statusCode === 404;
const falha = semVersao ? null : falhaDe(atual);
if (falha) return devolver([], [falha]);

const container = $('Encontrar contêiner').first().json;
const versao = semVersao ? null : atual.body;
const estado = versao
  ? `live v${versao.containerVersionId} · ${(versao.tag ?? []).length} tags · ${(versao.trigger ?? []).length} acionadores · ${(versao.variable ?? []).length} variáveis`
  : 'sem_versao_publicada';

const listaDe = (valor) => (Array.isArray(valor) ? valor : []);
const ids = (valor) => listaDe(valor).map(String).join(',');
const catalogo = [{
  _tabela: 'dim_conteiner',
  nome: container.name,
  contaGtmId: container.accountId,
  conteinerGtmId: container.containerId,
  contextoDeUso: container.usageContext,
  dominios: container.domainName,
}];

const workspacesOk = respostaDosWorkspaces.statusCode >= 200 && respostaDosWorkspaces.statusCode < 300;
for (const workspace of workspacesOk ? listaDe(respostaDosWorkspaces.body?.workspace) : []) {
  catalogo.push({ _tabela: 'dim_workspace', workspaceId: workspace.workspaceId, nome: workspace.name });
}

if (versao) {
  catalogo.push({
    _tabela: 'dim_versao',
    versaoId: versao.containerVersionId,
    nome: versao.name,
    totalTags: listaDe(versao.tag).length,
    totalAcionadores: listaDe(versao.trigger).length,
    totalVariaveis: listaDe(versao.variable).length,
  });
  for (const tag of listaDe(versao.tag)) {
    catalogo.push({
      _tabela: 'dim_tag',
      tagId: tag.tagId,
      nome: tag.name,
      tipo: tag.type,
      acionadoresDisparo: ids(tag.firingTriggerId),
      acionadoresBloqueio: ids(tag.blockingTriggerId),
      pausada: tag.paused === true,
    });
  }
  for (const acionador of listaDe(versao.trigger)) {
    catalogo.push({ _tabela: 'dim_acionador', acionadorId: acionador.triggerId, nome: acionador.name, tipo: acionador.type });
  }
  for (const variavel of listaDe(versao.variable)) {
    catalogo.push({ _tabela: 'dim_variavel', variavelId: variavel.variableId, nome: variavel.name, tipo: variavel.type });
  }
}

return devolver([{
  nome: container.name,
  estado,
  inactive: false,
  rotuloEsperado: contexto.fonte.nome ?? null,
  rotuloObservado: container.name,
}, ...catalogo], []);
